// Spanish (Nicaragua) for the game's interface: menus, panels, the inspector, the field guide,
// settings, and the messages the game sends. Written with vos, the way people talk in Nicaragua,
// and kept as plain as the English. The Chinandega map's own content is in es-chinandega.js.
import { addStrings, addPatterns, tr } from '../i18n.js';
import './es-chinandega.js';

const MONTHS = { March: 'marzo', April: 'abril', May: 'mayo', June: 'junio', July: 'julio', August: 'agosto', September: 'septiembre', October: 'octubre', November: 'noviembre', December: 'diciembre', January: 'enero', February: 'febrero' };
const M_RE = Object.keys(MONTHS).join('|');
const cap = s => s.charAt(0).toUpperCase() + s.slice(1);
const low = s => s.charAt(0).toLowerCase() + s.slice(1);
const date = s => tr(s); // a date inside a sentence, e.g. "March, Year 2"
// "un tigrillo", "una guatusa": close enough for the animal names on this map
const art = n => (/a$/.test(n.split(' ')[0]) ? 'una ' : 'un ') + n;
const DIR = { north: 'norte', east: 'este', south: 'sur', west: 'oeste' };
const LIMITS = { 'too shady': 'mucha sombra', 'too sunny': 'mucho sol', 'too dry': 'muy seco', 'too wet': 'muy húmedo', 'soil too poor': 'tierra muy pobre', 'cannot grow on this ground': 'no crece en este terreno' };
const limits = s => s.split(', ').map(x => LIMITS[x] || x).join(', ');
// units on progress lines ("12 / 60 trees")
const UNITS = {
  trees: 'árboles', tiles: 'cuadros', 'shaded tiles': 'cuadros con sombra', 'newly shaded tiles': 'cuadros nuevos con sombra', points: 'puntos', 'dollars more a month': 'dólares más al mes', mangroves: 'mangles', planted: 'sembrados', species: 'especies', seeded: 'sembrados',
};

